INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Bridge-Verbindung immer schneller als NAT?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt vom Setup ab"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig schneller"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkart wähle ich für direkten Zugriff aufs Host-Netzwerk?', 3, '[{"text": "Bridge", "correct": true, "because": "VMs im gleichen Netz wie Host"}, {"text": "NAT", "correct": false, "because": "Verbirgt VMs hinter Host-IP"}, {"text": "Isoliertes Netz", "correct": false, "because": "Kein Host-Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen NAT für mehrere VMs nützlich?', 5, '[{"text": "IP-Sparsamkeit", "correct": true, "because": "Nutzt eine Host-IP"}, {"text": "Einfache Einrichtung", "correct": true, "because": "Standard;y in vielen Hypervisors"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Nicht automatisch sicher"}, {"text": "Direkte Erreichbarkeit", "correct": false, "because": "VMs nicht direkt sichtbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bridge nutzt das Host-Netzwerk direkt. b) NAT braucht keine Portweiterleitung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Portweiterleitung oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl von NAT für eine VM?', 4, '[{"text": "Netzwerkkonnektivität", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Host-IP", "correct": false, "because": "Basis für NAT"}, {"text": "Externe IP pro VM", "correct": true, "because": "NAT teilt Host-IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bridge mehr IPs als NAT benötigt?', 2, '[{"text": "Ja", "correct": true, "because": "Jede VM braucht eigene IP"}, {"text": "Nein", "correct": false, "because": "NAT spart IPs"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für eine VM mit öffentlichem Zugriff?', 3, '[{"text": "Bridge", "correct": true, "because": "Direkte Netzwerkverbindung"}, {"text": "NAT", "correct": false, "because": "Versteckt VM hinter Host"}, {"text": "Lokale Isolation", "correct": false, "because": "Kein externer Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Bridge-Verbindung?', 5, '[{"text": "Direkte Netzwerkintegration", "correct": true, "because": "VMs wie physische Geräte"}, {"text": "Transparenz", "correct": true, "because": "Einfache Kommunikation"}, {"text": "IP-Sparsamkeit", "correct": false, "because": "Jede VM braucht IP"}, {"text": "Einfache Abschirmung", "correct": false, "because": "Weniger Isolation"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) NAT ist sicherer als Bridge. b) Bridge braucht keine Konfiguration. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Konfiguration nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für NAT in einem Testnetzwerk?', 4, '[{"text": "Host-Netzwerk", "correct": false, "because": "Basis für NAT"}, {"text": "Internetzugriff", "correct": false, "because": "Wichtig für Tests"}, {"text": "Eigene IPs pro VM", "correct": true, "because": "NAT teilt Host-IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist NAT für öffentliche Server geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Eingeschränkter direkter Zugriff"}, {"text": "Ja", "correct": false, "because": "Bridge besser für Sichtbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für Bridge in einem Unternehmensnetz wichtig?', 4, '[{"text": "Netzwerktransparenz", "correct": true, "because": "VMs wie physische Geräte"}, {"text": "Einfache Verwaltung", "correct": true, "because": "Direkte Integration"}, {"text": "IP-Einsparung", "correct": false, "because": "Jede VM braucht IP"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bridge die Sicherheit senkt. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Isolation als NAT"}, {"text": "Nein", "correct": false, "because": "Mit Konfiguration sicherbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für NAT in einem Heimnetzwerk?', 3, '[{"text": "Einfachheit", "correct": true, "because": "Schnelle Einrichtung"}, {"text": "Direkte Erreichbarkeit", "correct": false, "because": "Nicht Ziel von NAT"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Hardwareabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Bridge gibt VMs eigene IPs. b) NAT ist komplexer als Bridge.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, NAT oft einfacher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat NAT?', 5, '[{"text": "Eingeschränkte Erreichbarkeit", "correct": true, "because": "VMs hinter Host-IP"}, {"text": "Portweiterleitungsaufwand", "correct": true, "because": "Für Zugriff nötig"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Nicht automatisch"}, {"text": "Einfache Skalierung", "correct": false, "because": "Komplexer bei vielen VMs"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Bridge für einen Webserver unwichtig?', 3, '[{"text": "Netzwerkzugriff", "correct": false, "because": "Kern der Funktion"}, {"text": "Eigene IP", "correct": false, "because": "Öffentlich erreichbar"}, {"text": "IP-Sparsamkeit", "correct": true, "because": "Bridge spart keine IPs"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Erhöht NAT die Netzwerksicherheit?', 3, '[{"text": "Ja", "correct": true, "because": "Verbirgt VMs hinter Host"}, {"text": "Nein", "correct": false, "because": "Mit Konfiguration sicherer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Bridge für isolierte VMs geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Offen im Host-Netzwerk"}, {"text": "Ja", "correct": false, "because": "Weniger Isolation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkart wähle ich für eine Testumgebung?', 4, '[{"text": "NAT", "correct": true, "because": "Einfach und abgeschirmt"}, {"text": "Bridge", "correct": false, "because": "Zu offen für Tests"}, {"text": "Kein Netzwerk", "correct": false, "because": "Konnektivität oft nötig"}]');
